using Microsoft.AspNetCore.Mvc;

namespace YourApi;

public class ExceptionHandlingMiddleware
{
    private readonly RequestDelegate _next;
    private readonly ILogger<ExceptionHandlingMiddleware> _logger;

    public ExceptionHandlingMiddleware(RequestDelegate next, ILogger<ExceptionHandlingMiddleware> logger)
    {
        _next = next;
        _logger = logger;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        try
        {
            await _next(context);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Unhandled exception processing {Method} {Path}", context.Request.Method, context.Request.Path);

            var (statusCode, title) = ex switch
            {
                KeyNotFoundException   => (StatusCodes.Status404NotFound,   "Resource not found"),
                ArgumentException      => (StatusCodes.Status400BadRequest, "Invalid request"),
                InvalidOperationException => (StatusCodes.Status409Conflict, "Conflict"),
                _ => (StatusCodes.Status500InternalServerError, "An unexpected error occurred")
            };

            var problemDetails = new ProblemDetails
            {
                Status = statusCode,
                Title  = title,
                // Only surface the exception message for client errors, not 500s
                Detail = statusCode < 500 ? ex.Message : null,
                Instance = $"{context.Request.Method} {context.Request.Path}"
            };

            context.Response.StatusCode  = statusCode;
            context.Response.ContentType = "application/problem+json";
            await context.Response.WriteAsJsonAsync(problemDetails);
        }
    }
}

using YourApi;

var builder = WebApplication.CreateBuilder(args);

// Adds ProblemDetails support for automatic RFC 7807 responses
// from status-code pages, model validation, etc.
builder.Services.AddProblemDetails();

var app = builder.Build();

// Register the global exception middleware early in the pipeline
app.UseMiddleware<ExceptionHandlingMiddleware>();

// --- Example endpoints to demonstrate the behavior ---

app.MapGet("/items/{id}", (int id) =>
{
    if (id == 0)  throw new ArgumentException("Id must be greater than zero.");
    if (id == 99) throw new KeyNotFoundException($"Item {id} was not found.");
    if (id == 42) throw new InvalidOperationException("Item 42 is in a conflicting state.");
    if (id < 0)   throw new Exception("Something unexpected happened.");

    return Results.Ok(new { Id = id, Name = $"Item-{id}" });
});

app.Run();

